197	
198	    public InvoiceService(InvoiceRepository invoices, ProjectRepository projects, Audit audit) {
199	        this.invoices = invoices;
200	        this.projects = projects;
201	        this.audit = audit;
202	    }
203	
204	    @Transactional(readOnly = true)
205	    public List<InvoiceResponse> listForProject(Long projectId) {
206	        if (!projects.existsById(projectId)) {
207	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project");
208	        }
209	        return invoices.findByProjectIdOrderById(projectId).stream().map(InvoiceResponse::from).toList();
210	    }
211	
212	    /**
213	     * Every invoice across all projects, with the name of the project each one is for, narrowed to
214	     * the given status when one is supplied.
215	     */
216	    @Transactional(readOnly = true)
217	    public List<InvoiceSummaryResponse> listAll(InvoiceStatus status) {
218	        List<Invoice> found =
219	                status == null ? invoices.findAllWithProject() : invoices.findAllWithProjectByStatus(status);
220	        return found.stream().map(InvoiceSummaryResponse::from).toList();
221	    }
222	
223	    @Transactional
224	    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
225	        Project project = projects.findById(projectId)
226	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
227	        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
228	        LocalDate due = request.dueDate() != null ? request.dueDate() : issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS);
229	        if (due.isBefore(issued)) {
230	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
231	        }
232	        Invoice invoice = new Invoice(project, issued, due);
233	        if (request.amount() != null) {
234	            invoice.addLineItem(InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION, BigDecimal.ONE, request.amount());
235	        }
236	        Invoice saved = invoices.save(invoice);
237	        return InvoiceResponse.from(saved);
238	    }
239	
240	    /** A single invoice with its line items. */
241	    @Transactional(readOnly = true)
242	    public InvoiceDetailResponse get(Long projectId, Long invoiceId) {
243	        return InvoiceDetailResponse.from(find(projectId, invoiceId));
244	    }
245	
246	    /** Adds a line item to a draft invoice and reworks the invoice amount to match. */
247	    @Transactional
248	    public InvoiceDetailResponse addLineItem(Long projectId, Long invoiceId, LineItemRequest request) {
249	        Invoice invoice = findDraft(projectId, invoiceId);
250	        invoice.addLineItem(request.description().strip(), request.qty(), request.unitPrice());
251	        invoices.flush();
252	        return InvoiceDetailResponse.from(invoice);
253	    }
254	
255	    /** Changes a line item on a draft invoice and reworks the invoice amount to match. */
256	    @Transactional
257	    public InvoiceDetailResponse updateLineItem(Long projectId, Long invoiceId, Long lineItemId,
258	            LineItemRequest request) {
259	        Invoice invoice = findDraft(projectId, invoiceId);
260	        InvoiceLineItem item = findLineItem(invoice, lineItemId);
261	        invoice.updateLineItem(item, request.description().strip(), request.qty(), request.unitPrice());
262	        invoices.flush();
263	        return InvoiceDetailResponse.from(invoice);
264	    }
265	
266	    /** Removes a line item from a draft invoice and reworks the invoice amount to match. */
267	    @Transactional
268	    public InvoiceDetailResponse removeLineItem(Long projectId, Long invoiceId, Long lineItemId) {
269	        Invoice invoice = findDraft(projectId, invoiceId);
270	        invoice.removeLineItem(findLineItem(invoice, lineItemId));
271	        invoices.flush();
272	        return InvoiceDetailResponse.from(invoice);
273	    }
274	
275	    /** Sends a draft invoice and records the sending in the audit log. */
276	    @Transactional
277	    public InvoiceResponse send(Long projectId, Long invoiceId) {
278	        Invoice invoice = find(projectId, invoiceId);
279	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
280	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
281	        }
282	        if (invoice.getAmount().signum() == 0) {
283	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item before sending the invoice");
284	        }
285	        invoice.markSent();
286	        invoices.flush();
287	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
288	        return InvoiceResponse.from(invoice);
289	    }
290	
291	    /** Marks a sent invoice paid and records the payment in the audit log. */
292	    @Transactional
293	    public InvoiceResponse pay(Long projectId, Long invoiceId) {
294	        Invoice invoice = find(projectId, invoiceId);
295	        if (invoice.getStatus() != InvoiceStatus.SENT) {
296	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a sent invoice can be paid");
297	        }
298	        invoice.markPaid();
299	        invoices.flush();
300	        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
301	        return InvoiceResponse.from(invoice);
302	    }
303	
304	    private Invoice find(Long projectId, Long invoiceId) {
305	        return invoices.findById(invoiceId)
306	                .filter(i -> i.getProject().getId().equals(projectId))
307	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
308	    }
309	
310	    private Invoice findDraft(Long projectId, Long invoiceId) {
311	        Invoice invoice = find(projectId, invoiceId);
312	        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
313	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be changed");
314	        }
315	        return invoice;
316	    }
