  private readonly service = inject(InvoiceService);
  private readonly injector = inject(Injector);
  private readonly fb = inject(NonNullableFormBuilder);

  /** Bound from the `:projectId` route parameter. */
  readonly projectId = input.required<string>();
  /** Bound from the `:invoiceId` route parameter. */
  readonly invoiceId = input.required<string>();
  protected readonly projectIdNumber = computed(() => Number(this.projectId()));

  protected readonly invoice = rxResource({
    params: () => ({ projectId: this.projectIdNumber(), invoiceId: Number(this.invoiceId()) }),
    stream: ({ params }) => this.service.get(params.projectId, params.invoiceId),
  });

  // Work in whole cents so the total is exact rather than accumulating floating-point error.
  protected lineCents(qty: number, unitPrice: number): number {
    return Math.round(Math.round(qty * 100) * Math.round(unitPrice * 100) / 100);
  }
  protected readonly totalCents = computed(() =>
    (this.invoice.hasValue() ? this.invoice.value().lineItems : []).reduce(
      (sum, l) => sum + this.lineCents(l.qty, l.unitPrice),
      0,
    ),
  );

  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = this.fb.group({
    description: ['', [Validators.required, Validators.pattern(/\S/), Validators.maxLength(255)]],
    qty: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
    unitPrice: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
  });

  protected invalid(name: 'description' | 'qty' | 'unitPrice'): boolean {
    const control = this.form.controls[name];
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.saving.set(true);
    this.saveError.set(null);
    const { description, qty, unitPrice } = this.form.getRawValue();
    const item = { description: description.trim(), qty: Number(qty), unitPrice: Number(unitPrice) };
    this.service.addLineItem(this.projectIdNumber(), Number(this.invoiceId()), item).subscribe({
      next: (updated) => {
        this.invoice.set(updated);
        this.form.reset();
        this.saving.set(false);
      },
      error: () => {
        this.saveError.set('Could not add the line item. Please try again.');
        this.saving.set(false);
      },
    });
  }

  // The line item being changed in place, and whether a change or removal is in flight.
  protected readonly editingId = signal<number | null>(null);
  protected readonly busy = signal(false);
  protected readonly editError = signal<string | null>(null);

  protected readonly editForm = this.fb.group({
    description: ['', [Validators.required, Validators.pattern(/\S/), Validators.maxLength(255)]],
    qty: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
    unitPrice: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
  });

  protected startEdit(line: LineItem): void {
    this.editError.set(null);
    this.editForm.setValue({
      description: line.description,
      qty: String(line.qty),
      unitPrice: String(line.unitPrice),
    });
    this.editingId.set(line.id);
    this.focus(`lineitem-edit-description-${line.id}`);
  }

  protected cancelEdit(lineItemId: number): void {
    this.editingId.set(null);
    this.editError.set(null);
    this.focus(`lineitem-edit-${lineItemId}`);
  }

  protected saveEdit(lineItemId: number): void {
    if (this.editForm.invalid || this.busy()) {
      this.editForm.markAllAsTouched();
      return;
    }
    const { description, qty, unitPrice } = this.editForm.getRawValue();
    const item = { description: description.trim(), qty: Number(qty), unitPrice: Number(unitPrice) };
    this.run(
      this.service.updateLineItem(this.projectIdNumber(), Number(this.invoiceId()), lineItemId, item),
      'Could not save the line item. Please try again.',
      () => {
        this.editingId.set(null);
        this.focus(`lineitem-edit-${lineItemId}`);
      },
    );
  }

  protected remove(lineItemId: number): void {
    this.run(
      this.service.removeLineItem(this.projectIdNumber(), Number(this.invoiceId()), lineItemId),
      'Could not remove the line item. Please try again.',
      () => this.focus('invoice-lineitems-heading'),
    );
  }

  private run(request: Observable<InvoiceDetail>, failure: string, done: () => void): void {
    this.busy.set(true);
    this.editError.set(null);
    request.subscribe({
      next: (updated) => {
        this.invoice.set(updated);
        this.busy.set(false);
        done();
      },
      error: () => {
        this.editError.set(failure);
        this.busy.set(false);
      },
    });
  }

  // Moves focus once the view has re-rendered, so keyboard users are not left on a removed element.
  private focus(id: string): void {
    afterNextRender(() => document.getElementById(id)?.focus(), { injector: this.injector });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export const INVOICE_STATUSES = ['DRAFT', 'SENT', 'PAID'] as const;

export type InvoiceStatus = (typeof INVOICE_STATUSES)[number];

export interface Invoice {
  id: number;
  projectId: number;
  amount: number;
  status: InvoiceStatus;
  /** ISO date (yyyy-MM-dd) the invoice was issued. */
  issuedDate: string;
  /** ISO date (yyyy-MM-dd) payment is due. */
  dueDate: string;
}

/** An invoice as listed across all projects, with the name of the project it is for. */
export interface InvoiceSummary extends Invoice {
  projectName: string;
}

/** One thing an invoice charges for; its amount is quantity times unit price. */
export interface LineItem {
  id: number;
  description: string;
  qty: number;
  unitPrice: number;
  amount: number;
}

/** A single invoice with the line items it is built from. */
export interface InvoiceDetail extends Invoice {
  lineItems: LineItem[];
}

export interface NewLineItem {
  description: string;
  qty: number;
  unitPrice: number;
}

export interface NewInvoice {
  /** Raises the invoice as one figure; omit to start an empty draft built up from line items. */
  amount?: number;
  /** Defaults to today on the server when omitted. */
  issuedDate?: string;
  /** Defaults to 30 days after the issue date on the server when omitted. */
  dueDate?: string;
}

@Injectable({ providedIn: 'root' })
export class InvoiceService {
  private readonly http = inject(HttpClient);

  /** Every invoice across all projects, optionally narrowed to one status. */
  listAll(status?: InvoiceStatus): Observable<InvoiceSummary[]> {
    const params: Record<string, string> = status ? { status } : {};
    return this.http.get<InvoiceSummary[]>('/api/invoices', { params });
  }

  listForProject(projectId: number): Observable<Invoice[]> {
    return this.http.get<Invoice[]>(`/api/projects/${projectId}/invoices`);
  }

  create(projectId: number, invoice: NewInvoice): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices`, invoice);
  }

  get(projectId: number, invoiceId: number): Observable<InvoiceDetail> {
    return this.http.get<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}`);
  }

  addLineItem(projectId: number, invoiceId: number, item: NewLineItem): Observable<InvoiceDetail> {
    return this.http.post<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/line-items`, item);
  }

  updateLineItem(projectId: number, invoiceId: number, lineItemId: number, item: NewLineItem): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(
      `/api/projects/${projectId}/invoices/${invoiceId}/line-items/${lineItemId}`,
      item,
    );
  }

  removeLineItem(projectId: number, invoiceId: number, lineItemId: number): Observable<InvoiceDetail> {
    return this.http.delete<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/line-items/${lineItemId}`);
  }

  send(projectId: number, invoiceId: number): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices/${invoiceId}/send`, null);
  }

  pay(projectId: number, invoiceId: number): Observable<Invoice> {
    return this.http.post<Invoice>(`/api/projects/${projectId}/invoices/${invoiceId}/pay`, null);
  }
}

