-- A project can be deleted once it is no longer needed. Its tasks belong to it and go with it;
-- invoices are financial records, so the foreign key still blocks deleting a project that has any.
ALTER TABLE task DROP CONSTRAINT task_project_fk;
ALTER TABLE task ADD CONSTRAINT task_project_fk
    FOREIGN KEY (project_id) REFERENCES project (id) ON DELETE CASCADE;
CREATE TABLE invoice (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    CONSTRAINT invoice_project_fk FOREIGN KEY (project_id) REFERENCES project (id),
    CONSTRAINT invoice_amount_positive CHECK (amount > 0)
);

CREATE INDEX invoice_project_idx ON invoice (project_id);
-- Clients are archived rather than deleted: an archived client drops off the client list and search
-- but is kept, with its projects and contacts, and can be brought back.
ALTER TABLE client ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
